INSERT INTO exercises (id, level, order_in_level, title, theory, task_description, hint, expected_sql, expected_result_description, is_active) VALUES
(31, 1, 11, 'Товары с нулевым остатком', 'WHERE помогает выделить товары, которые нельзя отгрузить прямо сейчас.', 'Верните id, name, stock товаров, у которых stock равен нулю. Порядок: id по возрастанию.', 'Нужна таблица products.
Отфильтруйте stock = 0; выберите только три названных столбца.', 'SELECT id, name, stock FROM products WHERE stock = 0 ORDER BY id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(32, 1, 12, 'Города без повторов', 'DISTINCT убирает повторяющиеся значения выбранных столбцов.', 'Верните один столбец city: уникальные города клиентов. Отсортируйте city по возрастанию.', 'Работайте с customers, без JOIN.
DISTINCT применяется к city, сортировка — ORDER BY city.', 'SELECT DISTINCT city FROM customers ORDER BY city', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(33, 1, 13, 'Включённые границы цены', 'BETWEEN включает обе границы.', 'Верните id, name, price товаров с ценой от 15000 до 50000 включительно, по id.', 'Обе границы должны попасть в результат.
Используйте BETWEEN 15000 AND 50000.', 'SELECT id, name, price FROM products WHERE price BETWEEN 15000 AND 50000 ORDER BY id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(34, 1, 14, 'Заказы за календарный месяц', 'Даты YYYY-MM-DD можно сравнивать как текст. Полуоткрытый интервал удобен для границ месяца.', 'Верните id, order_date, customer_name заказов за май 2024 года, по id.', 'Начало периода: 2024-05-01.
Условие: дата >= начала и < 2024-06-01.', 'SELECT id, order_date, customer_name FROM orders WHERE order_date >= ''2024-05-01'' AND order_date < ''2024-06-01'' ORDER BY id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(35, 1, 15, 'Домен электронной почты', 'INSTR ищет позицию символа, SUBSTR берёт часть строки.', 'Для всех клиентов верните id, email, email_domain — часть email после @. Порядок: id.', 'Найдите @ через INSTR(email, ''@'').
Начните SUBSTR с позиции @ плюс 1; назовите столбец email_domain.', 'SELECT id, email, SUBSTR(email, INSTR(email, ''@'') + 1) AS email_domain FROM customers ORDER BY id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(36, 2, 13, 'Отзывы каждого клиента, включая ноль', 'LEFT JOIN сохраняет клиента без отзывов; COUNT(r.id) не считает пустую присоединённую строку.', 'Верните c.id, c.name, review_count для всех клиентов. Посчитайте их отзывы, включая 0, по c.id.', 'customers LEFT JOIN reviews по customer_id.
Считайте COUNT(r.id), а не COUNT(*); GROUP BY c.id, c.name.', 'SELECT c.id, c.name, COUNT(r.id) AS review_count FROM customers c LEFT JOIN reviews r ON r.customer_id = c.id GROUP BY c.id, c.name ORDER BY c.id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(37, 2, 14, 'Высоко оценённые товары', 'HAVING отбирает группы по агрегату. Округляйте среднее только при выводе.', 'Верните p.id, p.name, avg_rating товаров со средней оценкой >= 4.5. Округлите avg_rating до двух знаков, порядок p.id.', 'Соедините products и reviews по product_id.
Условие HAVING AVG(r.rating) >= 4.5, вывод ROUND(AVG(...), 2).', 'SELECT p.id, p.name, ROUND(AVG(r.rating), 2) AS avg_rating FROM products p JOIN reviews r ON r.product_id = p.id GROUP BY p.id, p.name HAVING AVG(r.rating) >= 4.5 ORDER BY p.id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(38, 2, 15, 'Товары без отзывов', 'NOT EXISTS проверяет отсутствие связанных строк.', 'Верните id, name товаров, для которых ещё нет ни одного отзыва, по id.', 'Отсутствие заказа и отсутствие отзыва — разные проверки.
Свяжите reviews.product_id с products.id в NOT EXISTS.', 'SELECT p.id, p.name FROM products p WHERE NOT EXISTS (SELECT 1 FROM reviews r WHERE r.product_id = p.id) ORDER BY p.id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(39, 2, 16, 'Города с несколькими клиентами', 'Группировка нужна по городу, а не по имени клиента.', 'Верните city, customer_count для городов хотя бы с двумя клиентами. Порядок city.', 'GROUP BY city, COUNT(*).
HAVING COUNT(*) >= 2.', 'SELECT city, COUNT(*) AS customer_count FROM customers GROUP BY city HAVING COUNT(*) >= 2 ORDER BY city', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(40, 2, 17, 'Выручка по месяцам', 'SUBSTR даты выделяет YYYY-MM, JOIN связывает количество с ценой.', 'Верните month, revenue по всем месяцам заказов. revenue = SUM(quantity * текущая price), округление до двух знаков; month по возрастанию.', 'Для учебной базы используем текущую каталожную цену; исторической цены в orders нет.
SUBSTR(order_date,1,7), JOIN products, GROUP BY month.', 'SELECT SUBSTR(o.order_date, 1, 7) AS month, ROUND(SUM(o.quantity * p.price), 2) AS revenue FROM orders o JOIN products p ON p.id = o.product_id GROUP BY SUBSTR(o.order_date, 1, 7) ORDER BY month', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(41, 3, 9, 'Последний отзыв каждого товара', 'ROW_NUMBER позволяет выбрать одну последнюю строку группы.', 'Верните product_id, review_id, rating, created_at самого позднего отзыва каждого товара с отзывами. При равной дате побеждает больший review_id. Порядок product_id.', 'CTE: ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY created_at DESC, id DESC).
Во внешнем запросе оставьте rn = 1; id назовите review_id.', 'WITH ranked AS (SELECT product_id, id AS review_id, rating, created_at, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY created_at DESC, id DESC) AS rn FROM reviews) SELECT product_id, review_id, rating, created_at FROM ranked WHERE rn = 1 ORDER BY product_id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(42, 3, 10, 'Заказы и отзывы без умножения строк', 'Две связи один-ко-многим лучше агрегировать до соединения.', 'Верните c.id, c.name, order_count, review_count для всех клиентов. Заказ считается строкой orders, отзыв — строкой reviews. Пустые счётчики замените на 0, порядок c.id.', 'Не соединяйте сырые orders и reviews одновременно: получите произведение строк.
Агрегируйте orders по customer_name и reviews по customer_id отдельно; затем два LEFT JOIN.', 'WITH oc AS (SELECT customer_name, COUNT(*) AS n FROM orders GROUP BY customer_name), rc AS (SELECT customer_id, COUNT(*) AS n FROM reviews GROUP BY customer_id) SELECT c.id, c.name, COALESCE(oc.n, 0) AS order_count, COALESCE(rc.n, 0) AS review_count FROM customers c LEFT JOIN oc ON oc.customer_name = c.name LEFT JOIN rc ON rc.customer_id = c.id ORDER BY c.id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(43, 3, 11, 'Сравнить зарплату с предыдущим наймом', 'LAG читает значение предыдущей строки окна; первая строка имеет NULL.', 'Верните id, name, department, salary, previous_salary, salary_delta. Сравнивайте с сотрудником, нанятым перед текущим в том же отделе, порядок окна hire_date, id. Итог отсортируйте по id. У первого previous_salary и salary_delta = NULL.', 'LAG(salary) OVER (PARTITION BY department ORDER BY hire_date, id).
salary_delta = salary - previous_salary. Для удобства используйте CTE.', 'WITH s AS (SELECT id, name, department, salary, LAG(salary) OVER (PARTITION BY department ORDER BY hire_date, id) AS previous_salary FROM employees) SELECT id, name, department, salary, previous_salary, salary - previous_salary AS salary_delta FROM s ORDER BY id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(44, 3, 12, 'Лидер категории по отзывам', 'Сначала агрегируйте оценки товара, затем ранжируйте внутри категории.', 'Верните category, product_id, name, avg_rating: один товар с наибольшей средней оценкой в каждой категории. Участвуют только товары с отзывами. При равенстве побеждает меньший product_id. avg_rating округлите до двух знаков только в выводе. Порядок category.', 'CTE для AVG по товару; второй CTE для ROW_NUMBER по категории.
Сортируйте окно по неокруглённому среднему DESC, id ASC; затем rn=1.', 'WITH ratings AS (SELECT p.id AS product_id, p.name, p.category, AVG(r.rating) AS avg_rating FROM products p JOIN reviews r ON r.product_id = p.id GROUP BY p.id, p.name, p.category), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY category ORDER BY avg_rating DESC, product_id) AS rn FROM ratings) SELECT category, product_id, name, ROUND(avg_rating, 2) AS avg_rating FROM ranked WHERE rn = 1 ORDER BY category', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1),
(45, 3, 13, 'Купили, но не оставили отзыв', 'NOT EXISTS может учитывать пару клиент–товар.', 'Верните customer_id, customer_name, product_id, product_name для уникальных пар клиент–купленный товар, если клиент не оставил отзыв именно на этот товар. Порядок customer_id, product_id.', 'Соедините customers.name с orders.customer_name; имена в этой учебной базе уникальны.
NOT EXISTS по reviews.customer_id и reviews.product_id; повторные покупки уберите DISTINCT.', 'SELECT DISTINCT c.id AS customer_id, c.name AS customer_name, p.id AS product_id, p.name AS product_name FROM customers c JOIN orders o ON o.customer_name = c.name JOIN products p ON p.id = o.product_id WHERE NOT EXISTS (SELECT 1 FROM reviews r WHERE r.customer_id = c.id AND r.product_id = p.id) ORDER BY customer_id, product_id', 'Столбцы и порядок строк указаны в условии. Проверяем результат, а не написание запроса.', 1);
